from collections import Counter, deque
def frames(grid):
    h,w=len(grid),len(grid[0])
    bg=Counter(v for r in grid for v in r).most_common(1)[0][0]
    seen=[[False]*w for _ in range(h)]; res=[]
    for i in range(h):
        for j in range(w):
            if grid[i][j]!=bg and not seen[i][j]:
                c=grid[i][j]; q=deque([(i,j)]); seen[i][j]=True; comp=[]
                while q:
                    x,y=q.popleft(); comp.append((x,y))
                    for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=x+dx,y+dy
                        if 0<=a<h and 0<=b<w and not seen[a][b] and grid[a][b]==c:
                            seen[a][b]=True; q.append((a,b))
                xs=[p[0] for p in comp]; ys=[p[1] for p in comp]
                r0,r1,c0,c1=min(xs),max(xs),min(ys),max(ys)
                perim=2*(r1-r0+1)+2*(c1-c0+1)-4
                if len(comp)==perim: res.append((r0,r1,c0,c1))
    return res
print(frames(inp))
print(frames(G['Test input']))

def transform(grid):
    h,w=len(grid),len(grid[0])
    bg=Counter(v for r in grid for v in r).most_common(1)[0][0]
    g=[row[:] for row in grid]
    for r0,r1,c0,c1 in frames(grid):
        ih,iw=r1-r0-1,c1-c0-1
        fill=2 if ih%2==0 and iw%2==0 else 7
        for i in range(r0+1,r1):
            for j in range(c0+1,c1):
                g[i][j]=fill
    return g
